-- ============================================================================
-- EC1 MID-YEAR RECUT: Cash Flow & NPV (cashflow) brought onto engines 3.12.3
-- (petrolord-engines a6cb037, PR #359; owner decision 2026-10-14: the course
-- must match the Suite). The valuation date is 31 December of the valuation
-- year; mid-year cash arrives half a year before it, so every mid-year exponent
-- is 0.5 SMALLER and mid-year NPV = end-year NPV x sqrt(1 + applied rate).
-- End-year figures do not move.
--
-- GENERATED by tools/course-waves/cashflow/midyear-recut/gen_migration.py from
-- tools/course-waves/cashflow/midyear-recut/edits.json. Never hand-edit.
--
-- WHAT MOVES.
--   cashflow questions: 21 rows (beginner 0, intermediate 21, advanced 0).
--     No keyed index moves (build_edits.py refuses one); every row keeps its id.
--   cashflow Professional capstone: the prompt's mid-year sentence, and one graded field
--     jv_npv_mid_year_usd 20030970.834339857 -> 21301227.52139557 (tol 1 USD).
--   No row count, ord, module key, scope, title, dataset or other field moves.
--   The lessons, panels and lab ship in the NextGen site build.
--
-- ATTEMPTS AND CERTIFICATES. academy_grade_quiz scores a quiz attempt once, at
-- submission, against the answer_index of each question id; academy_submit_capstone
-- scores a capstone attempt once and stores the score. Neither is ever re-run, no
-- trigger exists on academy_quiz_questions or academy_capstones, and this file
-- touches neither attempts table nor academy_certifications. It REPORTS (NOTICE)
-- every cashflow attempt and certification it finds, and asserts that all of them
-- are byte-identical after it. (Read-only production check 2026-10-14: 0 cashflow
-- quiz attempts, 0 capstone attempts, 0 certifications.)
--
-- GUARDS. Each question row is addressed by (app_slug, tier, scope, module_key,
-- ord) and must carry EITHER its served prompt, options, answer_index and
-- explanation exactly (it is updated) OR the recut ones exactly (already applied,
-- left alone). Anything else raises, and in a transaction the whole file rolls
-- back. Every update touches exactly 1 row. The capstone is guarded the same way.
--
-- TRANSACTION. Like every migration in this repository the file carries no
-- begin/commit of its own: apply_ec1_midyear.sh wraps it in one.
-- SAFE TO RE-RUN: a second run finds every row recut and writes nothing.
-- ============================================================================

-- 0. The attempts and certifications that stand as issued.
do $$
declare
  v_q integer; v_c integer; v_k integer;
begin
  select count(*) into v_q from public.academy_quiz_attempts where app_slug = 'cashflow';
  select count(*) into v_c from public.academy_capstone_attempts where app_slug = 'cashflow';
  select count(*) into v_k from public.academy_certifications where app_slug = 'cashflow';
  raise notice 'ec1 midyear recut: cashflow holds % quiz attempt(s), % capstone attempt(s), % certification(s); all stand as graded and none is re-scored', v_q, v_c, v_k;
  perform set_config('ec1mid.snapshot', md5(coalesce((select string_agg(md5(a::text), ',' order by a.id) from public.academy_capstone_attempts a where a.app_slug = 'cashflow'), '') || '#' || coalesce((select string_agg(md5(q::text), ',' order by q.id) from public.academy_quiz_attempts q where q.app_slug = 'cashflow'), '') || '#' || coalesce((select string_agg(md5(c::text), ',' order by c.id) from public.academy_certifications c where c.app_slug = 'cashflow'), '')), false);
end $$;

-- 1. cashflow: 21 question rows.
do $$
declare
  r         record;
  v_state   text;
  v_count   integer;
  v_updated integer := 0;
  v_done    integer := 0;
begin
  for r in
    select * from (values
      ('intermediate', 'final', null::text, 2, 'Under mid-year discounting on the nominal basis AKATA''s 2029 row reads -115486897.55 in the discounted column instead of -121123680.00. What happened to the valuation year row?', '["It was shifted by half a year like every other row, so the capex is divided by the square root of 1.1 even though it sits in the valuation year.", "It was deflated by half a year of the 3 percent inflation, because mid-year timing moves the base date for the real column as well.", "The 45000000.00 of 2030 capex was netted into it, since mid-year timing brings the following year''s spend forward by half a year.", "Nothing was discounted; the row is printed net of its 2029 depreciation of 21000000.00 under mid-year, and the exponent is still zero in the valuation year."]'::jsonb, 0, 'The whole column is scaled by one factor, which is why the mid-year NPV of 69159247.46 sits closer to 72534830.66 than a reader who shifts only the revenue years would compute.', 'Under mid-year discounting on the nominal basis AKATA''s 2029 row reads -127035587.31 in the discounted column instead of -121123680.00. What happened to the valuation year row?', '["It was moved half a year like every other row, so the capex is multiplied by the square root of 1.1 even though it sits in the valuation year.", "It was deflated by half a year of the 3 percent inflation, because mid-year timing moves the base date for the real column as well.", "The 45000000.00 of 2030 capex was netted into it, since mid-year timing brings the following year''s spend forward by half a year.", "Nothing was discounted; the row is printed net of its 2029 depreciation of 21000000.00 under mid-year, and the exponent is still zero in the valuation year."]'::jsonb, 0, 'The whole column is scaled by one factor, which is why the mid-year NPV of 76075172.20 sits closer to 72534830.66 than a reader who shifts only the revenue years would compute.'),
      ('intermediate', 'final', null::text, 3, 'mid_year_discounting reports NPV 20586124.09 against 21590909.09 for its end-year twin, yet DPI 0.431818 and discounted take 82.2761 percent are identical in both. What separates the readings that move from those that hold?', '["The DPI and the take are undiscounted readings, so the convention has no exponent to shift in them.", "The mid-year shift applies to the 2031 row only, and the DPI and the take are read on the 2030 row where nothing moved.", "The NPV is evaluated on the real flows and the ratios on the nominal flows, and the convention touches only the real column.", "A sum of present values moves when every row is scaled by one factor; a ratio of two present values scaled by the same factor does not."]'::jsonb, 3, 'The same reasoning holds AKATA''s discounted payback at 3.961607 years under all four combinations of basis and convention.', 'mid_year_discounting reports NPV 22644736.49 against 21590909.09 for its end-year twin, yet DPI 0.431818 and discounted take 82.2761 percent are identical in both. What separates the readings that move from those that hold?', '["The DPI and the take are undiscounted readings, so the convention has no exponent to shift in them.", "The mid-year shift applies to the 2031 row only, and the DPI and the take are read on the 2030 row where nothing moved.", "The NPV is evaluated on the real flows and the ratios on the nominal flows, and the convention touches only the real column.", "A sum of present values moves when every row is scaled by one factor; a ratio of two present values scaled by the same factor does not."]'::jsonb, 3, 'The same reasoning holds AKATA''s discounted payback at 3.961607 years under all four combinations of basis and convention.'),
      ('intermediate', 'final', null::text, 4, 'A summary table lists two projects at 219158380.04 and 212070544.45. What is a reader entitled to conclude from those two figures?', '["That the second project is worth less, since NPVs on the same ledger scale are directly comparable whatever their convention.", "Nothing until the conventions are attached: they are one field, multiyear_pia_real, read end-year and mid-year.", "That the second project carries the higher discount rate, since a lower NPV on a similar field is the mark of a harsher rate.", "That the two differ by a valuation year, since a shift of one year at 6.796117 percent is about the size of the gap."]'::jsonb, 1, 'At 5 percent their profiles read 239552507.28 and 233779309.33, and every difference between the two columns is the half-year shift.', 'A summary table lists two projects at 219158380.04 and 226483105.72. What is a reader entitled to conclude from those two figures?', '["That the second project is worth more, since NPVs on the same ledger scale are directly comparable whatever their convention.", "Nothing until the conventions are attached: they are one field, multiyear_pia_real, read end-year and mid-year.", "That the first project carries the higher discount rate, since a lower NPV on a similar field is the mark of a harsher rate.", "That the two differ by a valuation year, since a shift of one year at 6.796117 percent is about the size of the gap."]'::jsonb, 1, 'At 5 percent their profiles read 239552507.28 and 245468274.80, and every difference between the two columns is the half-year shift.'),
      ('intermediate', 'final', null::text, 37, 'A reader reports AKATA''s NPV as 70188970.32, and only afterwards discovers that the run was mid-year on the real basis. What does the method call this?', '["A reconciliation problem: the two facts are consistent, and the reader has only to restate 70188970.32 on the nominal basis, where the mid-year figure of 69159247.46 is the same claim about the same rows in other money.", "Working the steps out of order: every number changes meaning when a convention is found late, and naming the convention first is what stops the numbers betraying you.", "A sunk-year problem: a mid-year run on the real basis sinks the valuation year row by discounting it half a year, so the reader is holding an NPV with the 2029 capex partly written off and needs the sunk figure of 206819768.67 to compare.", "A basis problem: 70188970.32 is the real basis figure and the reader needs the nominal 69159247.46 to proceed."]'::jsonb, 1, 'The convention sentence is written first; 70188970.32 is real basis, mid-year, 10 percent nominal, 3 percent inflation, valued in 2029, and a reader who learns that last has read the number wrong until then.', 'A reader reports AKATA''s NPV as 74959094.51, and only afterwards discovers that the run was mid-year on the real basis. What does the method call this?', '["A reconciliation problem: the two facts are consistent, and the reader has only to restate 74959094.51 on the nominal basis, where the mid-year figure of 76075172.20 is the same claim about the same rows in other money.", "Working the steps out of order: every number changes meaning when a convention is found late, and naming the convention first is what stops the numbers betraying you.", "A sunk-year problem: a mid-year run on the real basis moves the valuation year row by half a year, so the reader is holding an NPV with the 2029 capex partly written off and needs the sunk figure of 206819768.67 to compare.", "A basis problem: 74959094.51 is the real basis figure and the reader needs the nominal 76075172.20 to proceed."]'::jsonb, 1, 'The convention sentence is written first; 74959094.51 is real basis, mid-year, 10 percent nominal, 3 percent inflation, valued in 2029, and a reader who learns that last has read the number wrong until then.'),
      ('intermediate', 'final', null::text, 38, 'The onward lesson says the Expert tier''s fiscal cascade is read with the conventions this tier named. What does that mean for a PIA NPV such as 219158380.04 on multiyear_pia_real?', '["It carries the same label: real basis, end-year, 10 percent nominal at 3 percent inflation, applied 6.796117; its mid-year twin reads 212070544.45 and its applied-rate profile point reads the headline, as AKATA''s does.", "It is convention-free, because the PIA cascade is charged on undiscounted bases and the NPV is a sum of after-tax rows, so the discount rate, the basis and the timing convention enter only the JV ledger, and a PIA NPV is the same number under every reading of time.", "It needs its own conventions, because five taxes on three bases each carry a timing rule that the JV ledger does not, so the royalty, the HCT, the CIT and the levy are each placed in time separately and a PIA NPV is labelled by the timing of each tax rather than by one convention.", "It is read nominal only, because the PIA''s price royalty tiers are in money of the day and cannot be deflated, so the real basis is refused on a PIA run and the profile is evaluated on the nominal flows at the nominal 10.000000 percent with no Fisher conversion and no rounding gap."]'::jsonb, 0, 'Nothing learned in the Professional tier is replaced in the Expert tier; multiyear_pia_nominal reads 219158380.04 too, because the bases agree end-year.', 'The onward lesson says the Expert tier''s fiscal cascade is read with the conventions this tier named. What does that mean for a PIA NPV such as 219158380.04 on multiyear_pia_real?', '["It carries the same label: real basis, end-year, 10 percent nominal at 3 percent inflation, applied 6.796117; its mid-year twin reads 226483105.72 and its applied-rate profile point reads the headline, as AKATA''s does.", "It is convention-free, because the PIA cascade is charged on undiscounted bases and the NPV is a sum of after-tax rows, so the discount rate, the basis and the timing convention enter only the JV ledger, and a PIA NPV is the same number under every reading of time.", "It needs its own conventions, because five taxes on three bases each carry a timing rule that the JV ledger does not, so the royalty, the HCT, the CIT and the levy are each placed in time separately and a PIA NPV is labelled by the timing of each tax rather than by one convention.", "It is read nominal only, because the PIA''s price royalty tiers are in money of the day and cannot be deflated, so the real basis is refused on a PIA run and the profile is evaluated on the nominal flows at the nominal 10.000000 percent with no Fisher conversion and no rounding gap."]'::jsonb, 0, 'Nothing learned in the Professional tier is replaced in the Expert tier; multiyear_pia_nominal reads 219158380.04 too, because the bases agree end-year.'),
      ('intermediate', 'final', null::text, 42, 'AKATA reads 72534830.66 under nominal end-year and under real end-year, 69159247.46 under nominal mid-year and 70188970.32 under real mid-year. Which of basis and convention moves NPV, and when does the other begin to?', '["The basis always moves it, by the deflation of 141637829.18 to 117362408.71; the convention only moves it on the nominal basis.", "The convention always moves it; the basis moves it only under mid-year, where the half-year factor differs between 10.000000 and 6.796117 percent.", "Both always move it, and the two end-year figures agree by the coincidence of 3 percent inflation against 2 percent escalators, which happen to offset each other over AKATA''s seven years.", "Neither moves it on its own; only the two changed together, from nominal end-year to real mid-year, produce a different figure, because each alone is a relabelling of the same discounted column."]'::jsonb, 1, 'Under end-year the deflated flows at the deflated rate multiply back to the nominal factor exactly; under mid-year the half-year shift is a square root of a different number on each basis.', 'AKATA reads 72534830.66 under nominal end-year and under real end-year, 76075172.20 under nominal mid-year and 74959094.51 under real mid-year. Which of basis and convention moves NPV, and when does the other begin to?', '["The basis always moves it, by the deflation of 141637829.18 to 117362408.71; the convention only moves it on the nominal basis.", "The convention always moves it; the basis moves it only under mid-year, where the half-year factor differs between 10.000000 and 6.796117 percent.", "Both always move it, and the two end-year figures agree by the coincidence of 3 percent inflation against 2 percent escalators, which happen to offset each other over AKATA''s seven years.", "Neither moves it on its own; only the two changed together, from nominal end-year to real mid-year, produce a different figure, because each alone is a relabelling of the same discounted column."]'::jsonb, 1, 'Under end-year the deflated flows at the deflated rate multiply back to the nominal factor exactly; under mid-year the half-year shift is a square root of a different number on each basis.'),
      ('intermediate', 'module', 'm01-why-time-matters'::text, 4, 'jv_analytic_decision_kpis has a 2030 flow of minus 12500000.00 and a 2031 flow of 37500000.00, base year 2030, 10 percent, nominal, end-year. What is its NPV?', '["25000000.00, the plain sum of the rows, since two years is too short to discount.", "21590909.09, the first row whole plus the second divided by 1.1 once, 34090909.09.", "20586124.09, both rows divided by the square root of 1.1 because each sits half a year from the base date.", "23750000.00, because the 2030 flow is a year older than the 2031 flow and is carried forward by 1.1 to meet it."]'::jsonb, 1, 'The undiscounted total is 25000000.00; the discount touches the 2031 row alone, 37500000.00 to 34090909.09.', 'jv_analytic_decision_kpis has a 2030 flow of minus 12500000.00 and a 2031 flow of 37500000.00, base year 2030, 10 percent, nominal, end-year. What is its NPV?', '["25000000.00, the plain sum of the rows, since two years is too short to discount.", "21590909.09, the first row whole plus the second divided by 1.1 once, 34090909.09.", "22644736.49, both rows multiplied by the square root of 1.1 because each arrives half a year before its year end.", "23750000.00, because the 2030 flow is a year older than the 2031 flow and is carried forward by 1.1 to meet it."]'::jsonb, 1, 'The undiscounted total is 25000000.00; the discount touches the 2031 row alone, 37500000.00 to 34090909.09.'),
      ('intermediate', 'module', 'm01-why-time-matters'::text, 9, 'Under mid_year_discounting the 2030 row goes from minus 12500000.00 to minus 11918282.37, the 2031 row to 32504406.45, and the NPV is 20586124.09 against the end-year 21590909.09. What is the relation between the two NPVs?', '["Mid-year shifts only the 2031 row by half a year, so the 2030 row stays at minus 12500000.00 and the NPV falls by the change in one row.", "The mid-year NPV is the end-year NPV divided by 1.1 once more, a full extra year on every row, which is why it is lower.", "The difference is the fiscal cascade: royalty of 20000000.00 is charged mid-year and tax of 32500000.00 at year end, so the timing of the two moves the sum.", "The mid-year NPV is the end-year NPV divided by the square root of 1.1, because every exponent moved by half."]'::jsonb, 3, 'Every row, the base year row included, was scaled by one factor, so the sum was scaled by the same factor.', 'Under mid_year_discounting the 2030 row goes from minus 12500000.00 to minus 13110110.60, the 2031 row to 35754847.10, and the NPV is 22644736.49 against the end-year 21590909.09. What is the relation between the two NPVs?', '["Mid-year shifts only the 2031 row by half a year, so the 2030 row stays at minus 12500000.00 and the NPV rises by the change in one row.", "The mid-year NPV is the end-year NPV multiplied by 1.1, a full year earlier on every row, which is why it is higher.", "The difference is the fiscal cascade: royalty of 20000000.00 is charged mid-year and tax of 32500000.00 at year end, so the timing of the two moves the sum.", "The mid-year NPV is the end-year NPV multiplied by the square root of 1.1, because every exponent fell by half."]'::jsonb, 3, 'Every row, the base year row included, was scaled by one factor, so the sum was scaled by the same factor.'),
      ('intermediate', 'module', 'm01-why-time-matters'::text, 10, 'AKATA reads 72534830.66 end-year and 69159247.46 mid-year on the nominal basis, but 72534830.66 and 70188970.32 on the real basis. Why do the two conventions differ less on the real basis?', '["The real flows are smaller, 117362408.71 against 141637829.18 in total, so there is less for the half-year shift to remove.", "Half a year at 6.796117 percent is a smaller division than half a year at 10 percent.", "The real basis shifts only the years after 2029, leaving the capex row whole.", "The real basis deflates the half-year shift by 3 percent of inflation on top of the rate, and the two shifts partly cancel."]'::jsonb, 1, 'The nominal gap runs 72534830.66 to 69159247.46; the real gap only 72534830.66 to 70188970.32.', 'AKATA reads 72534830.66 end-year and 76075172.20 mid-year on the nominal basis, but 72534830.66 and 74959094.51 on the real basis. Why do the two conventions differ less on the real basis?', '["The real flows are smaller, 117362408.71 against 141637829.18 in total, so there is less for the half-year shift to add.", "Half a year at 6.796117 percent is a smaller factor than half a year at 10 percent.", "The real basis shifts only the years after 2029, leaving the capex row whole.", "The real basis deflates the half-year shift by 3 percent of inflation on top of the rate, and the two shifts partly cancel."]'::jsonb, 1, 'The nominal gap runs 72534830.66 to 76075172.20; the real gap only 72534830.66 to 74959094.51.'),
      ('intermediate', 'module', 'm01-why-time-matters'::text, 12, 'A reader hand-checks AKATA''s mid-year NPV by shifting the 2030 to 2035 rows by half a year and leaving the 2029 row whole at minus 121123680.00. What happens?', '["The check reconciles, because the base year row carries an exponent of zero under either convention and cannot move.", "The check lands on 70188970.32, because leaving the capex row whole is what the real basis does under mid-year.", "The check will not reconcile: the engine discounts the valuation year row too, to minus 115486897.55.", "The check produces a smaller gap than 72534830.66 to 69159247.46, because the capex left at full size pulls the sum down."]'::jsonb, 2, 'Discounting the 2029 capex by half a year makes it cheaper in present value and partly offsets the shrinking of the revenue rows, so the true gap is smaller than the reader computes.', 'A reader hand-checks AKATA''s mid-year NPV by shifting the 2030 to 2035 rows by half a year and leaving the 2029 row whole at minus 121123680.00. What happens?', '["The check reconciles, because the base year row carries an exponent of zero under either convention and cannot move.", "The check lands on 74959094.51, because leaving the capex row whole is what the real basis does under mid-year.", "The check will not reconcile: the engine moves the valuation year row too, compounding it to minus 127035587.31.", "The check produces a smaller gap than 72534830.66 to 76075172.20, because the capex left at full size pulls the sum down."]'::jsonb, 2, 'Compounding the 2029 capex forward by half a year makes it dearer in present value and partly offsets the lift of the revenue rows, so the true gap is smaller than the reader computes.'),
      ('intermediate', 'module', 'm01-why-time-matters'::text, 13, 'One project is run end-year and reports 72534830.66; another is run mid-year and reports 69159247.46. Can they be ranked on those NPVs?', '["No. Between the two figures there is no information about either field, only a convention, and both must be run under the same one first.", "Yes, because mid-year is the more accurate convention and its lower figure is the conservative one to rank on.", "Yes, because the IRR of 29.2361 percent and the discounted payback of 3.961607 years are the same under both conventions, which shows that the NPVs are comparable too.", "Yes, provided both are on the nominal basis, since basis is the only setting that changes NPV."]'::jsonb, 0, 'The IRR and the discounted payback of 3.961607 years are unmoved by the convention; the NPV is not, so it cannot cross a convention boundary.', 'One project is run end-year and reports 72534830.66; another is run mid-year and reports 76075172.20. Can they be ranked on those NPVs?', '["No. Between the two figures there is no information about either field, only a convention, and both must be run under the same one first.", "Yes, because mid-year is the more accurate convention and its higher figure is the better estimate to rank on.", "Yes, because the IRR of 29.2361 percent and the discounted payback of 3.961607 years are the same under both conventions, which shows that the NPVs are comparable too.", "Yes, provided both are on the nominal basis, since basis is the only setting that changes NPV."]'::jsonb, 0, 'The IRR and the discounted payback of 3.961607 years are unmoved by the convention; the NPV is not, so it cannot cross a convention boundary.'),
      ('intermediate', 'module', 'm01-why-time-matters'::text, 15, 'Which of AKATA''s two conventions, end-year or mid-year, is the true one?', '["Mid-year, because the published mid_year_discounting case is the golden the engine was validated against.", "The engine cannot say: the rows are years, nothing records when within a year the cash moved, and choosing mid-year is a claim about the field that the engine will not check.", "End-year, because it gives the higher NPV of 72534830.66 and the engine reports the higher of the two readings.", "The engine tests both and keeps the one whose discounted payback matches the undiscounted 3.461632 years."]'::jsonb, 1, 'Where none is given it discounts end-year, and a default is still a choice the reader has to be told.', 'Which of AKATA''s two conventions, end-year or mid-year, is the true one?', '["Mid-year, because the published mid_year_discounting case is the golden the engine was validated against.", "The engine cannot say: the rows are years, nothing records when within a year the cash moved, and choosing mid-year is a claim about the field that the engine will not check.", "End-year, because it gives the lower NPV of 72534830.66 and the engine reports the more cautious of the two readings.", "The engine tests both and keeps the one whose discounted payback matches the undiscounted 3.461632 years."]'::jsonb, 1, 'Where none is given it discounts end-year, and a default is still a choice the reader has to be told.'),
      ('intermediate', 'module', 'm02-real-and-nominal'::text, 9, 'Under mid-year discounting AKATA''s nominal basis gives 69159247.46 and its real basis 70188970.32, after agreeing at 72534830.66 under end-year. Why do the bases part?', '["The half-year shift divides by the square root of one plus the applied rate, and the applied rates differ, so the shift is smaller on the real basis.", "The real basis under mid-year deflates the 2029 row as well, which the end-year run had left whole.", "Mid-year shifts the real flows by half a year of inflation on top of half a year of the rate, and the two shifts compound.", "The half-year shift is taken at the inflation rate of 3 percent rather than at the applied rate on each basis."]'::jsonb, 0, 'Basis does not move NPV under end-year; under mid-year it does, by about a million USD on AKATA.', 'Under mid-year discounting AKATA''s nominal basis gives 76075172.20 and its real basis 74959094.51, after agreeing at 72534830.66 under end-year. Why do the bases part?', '["The half-year shift multiplies by the square root of one plus the applied rate, and the applied rates differ, so the shift is smaller on the real basis.", "The real basis under mid-year deflates the 2029 row as well, which the end-year run had left whole.", "Mid-year shifts the real flows by half a year of inflation on top of half a year of the rate, and the two shifts compound.", "The half-year shift is taken at the inflation rate of 3 percent rather than at the applied rate on each basis."]'::jsonb, 0, 'Basis does not move NPV under end-year; under mid-year it does, by about a million USD on AKATA.'),
      ('intermediate', 'module', 'm03-net-present-value'::text, 9, 'AKATA is switched from end-year to mid-year discounting. What happens to its discounted payback?', '["It moves half a year later, because every exponent has been shifted by half.", "Nothing; it is 3.961607 years under all four combinations of basis and convention.", "It moves earlier, because the 2029 capex shrinks to minus 115486897.55 and the hole is shallower.", "It becomes 3.461632 years, because mid-year timing removes the gap between the two paybacks."]'::jsonb, 1, 'The mid-year shift scales every discounted row by one factor, and a crossing does not move when everything is scaled together.', 'AKATA is switched from end-year to mid-year discounting. What happens to its discounted payback?', '["It moves half a year earlier, because every exponent has been brought forward by half.", "Nothing; it is 3.961607 years under all four combinations of basis and convention.", "It moves later, because the 2029 capex grows to minus 125171883.54 and the hole is deeper.", "It becomes 3.461632 years, because mid-year timing removes the gap between the two paybacks."]'::jsonb, 1, 'The mid-year shift scales every discounted row by one factor, and a crossing does not move when everything is scaled together.'),
      ('intermediate', 'module', 'm04-the-internal-rate-of-return'::text, 1, 'AKATA reports NPV 72534830.66 end-year and 70188970.32 mid-year on the real basis, and 69159247.46 mid-year on the nominal basis. What does the IRR read across those three runs?', '["29.2361 percent end-year, and a lower root under mid-year, because the half-year shift discounts every receipt harder and the curve crosses zero sooner.", "29.2361 percent on the nominal basis and 6.796117 percent on the real basis, since the real run discounts at the applied real rate.", "29.2361 percent in every one of them.", "Three roots, one per NPV."]'::jsonb, 2, 'The IRR is solved from the nominal flow vector alone, and neither the basis, the convention nor the discount rate enters that vector.', 'AKATA reports NPV 72534830.66 end-year and 74959094.51 mid-year on the real basis, and 76075172.20 mid-year on the nominal basis. What does the IRR read across those three runs?', '["29.2361 percent end-year, and a higher root under mid-year, because the half-year shift discounts every receipt less and the curve crosses zero later.", "29.2361 percent on the nominal basis and 6.796117 percent on the real basis, since the real run discounts at the applied real rate.", "29.2361 percent in every one of them.", "Three roots, one per NPV."]'::jsonb, 2, 'The IRR is solved from the nominal flow vector alone, and neither the basis, the convention nor the discount rate enters that vector.'),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 3, 'Step three reads AKATA''s NPV under both conventions, 72534830.66 end-year and 70188970.32 mid-year on the real basis. What does the method say to report?', '["The pair with its convention on each, because the pair is the answer and neither number alone is.", "The mid-year figure of 70188970.32, because it is the lower of the two and a decision should rest on the conservative reading.", "The end-year figure of 72534830.66, because the engine defaults to end-year and the default is the engine''s statement of the true convention.", "The mean of the two, because the true timing of cash inside a year lies between the conventions and averaging removes the convention error."]'::jsonb, 0, 'The rows are identical under both readings, and 69159247.46 is the same field mid-year on the nominal basis; no one of the three is more true than the others.', 'Step three reads AKATA''s NPV under both conventions, 72534830.66 end-year and 74959094.51 mid-year on the real basis. What does the method say to report?', '["The pair with its convention on each, because the pair is the answer and neither number alone is.", "The mid-year figure of 74959094.51, because it is the higher of the two and cash really does arrive through the year.", "The end-year figure of 72534830.66, because the engine defaults to end-year and the default is the engine''s statement of the true convention.", "The mean of the two, because the true timing of cash inside a year lies between the conventions and averaging removes the convention error."]'::jsonb, 0, 'The rows are identical under both readings, and 76075172.20 is the same field mid-year on the nominal basis; no one of the three is more true than the others.'),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 7, 'Six conventions label 72534830.66. Which single change moves it to 70188970.32, and which to 206819768.67?', '["Real to nominal basis moves it to 70188970.32, because the deflator comes out of the rows; a 2030 valuation year with prior years kept moves it to 206819768.67.", "Inflation from 3 to 8 percent moves it to 70188970.32; valuing from 2031 with prior years kept moves it to 206819768.67.", "End-year to mid-year moves it to 70188970.32; a 2030 valuation year with prior years treated as sunk moves it to 206819768.67.", "The nominal rate from 10 to 12 percent moves it to 70188970.32; an abandonment of 60000000 in 2035 moves it to 206819768.67."]'::jsonb, 2, 'Basis does not move NPV end-year, inflation never does on the real basis with the escalators set, 2030 with prior years kept gives 77464382.26, and the 60000000 abandonment gives 38666394.86.', 'Six conventions label 72534830.66. Which single change moves it to 74959094.51, and which to 206819768.67?', '["Real to nominal basis moves it to 74959094.51, because the deflator comes out of the rows; a 2030 valuation year with prior years kept moves it to 206819768.67.", "Inflation from 3 to 8 percent moves it to 74959094.51; valuing from 2031 with prior years kept moves it to 206819768.67.", "End-year to mid-year moves it to 74959094.51; a 2030 valuation year with prior years treated as sunk moves it to 206819768.67.", "The nominal rate from 10 to 12 percent moves it to 74959094.51; an abandonment of 60000000 in 2035 moves it to 206819768.67."]'::jsonb, 2, 'Basis does not move NPV end-year, inflation never does on the real basis with the escalators set, 2030 with prior years kept gives 77464382.26, and the 60000000 abandonment gives 38666394.86.'),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 8, 'The tier ends on the sentence that IRR is a property of a curve rather than of a project. What is the sentence claiming?', '["That the IRR is a zero of one vector''s NPV curve: a curve with two zeros has no single IRR, which is why the engine returns null there, and a scaled vector keeps its IRR at any size.", "That the IRR moves when the convention moves, as NPV does from 72534830.66 to 70188970.32, because the curve is redrawn under mid-year discounting.", "That the IRR is a rate on the project''s money, so a project with an IRR of 29.2361 percent earns 29.2361 percent on its 255000000.00 of capex.", "That the IRR is read from the sampled profile, so AKATA''s 29.2361 percent is where the profile crosses zero between the 15 and 20 percent points."]'::jsonb, 0, '29.2361 percent holds at every working interest and under all four conventions; [-100, 208, -108.12] is zero at 2.0000 and at 6.0000 percent, so the engine names neither and returns null with both listed.', 'The tier ends on the sentence that IRR is a property of a curve rather than of a project. What is the sentence claiming?', '["That the IRR is a zero of one vector''s NPV curve: a curve with two zeros has no single IRR, which is why the engine returns null there, and a scaled vector keeps its IRR at any size.", "That the IRR moves when the convention moves, as NPV does from 72534830.66 to 74959094.51, because the curve is redrawn under mid-year discounting.", "That the IRR is a rate on the project''s money, so a project with an IRR of 29.2361 percent earns 29.2361 percent on its 255000000.00 of capex.", "That the IRR is read from the sampled profile, so AKATA''s 29.2361 percent is where the profile crosses zero between the 15 and 20 percent points."]'::jsonb, 0, '29.2361 percent holds at every working interest and under all four conventions; [-100, 208, -108.12] is zero at 2.0000 and at 6.0000 percent, so the engine names neither and returns null with both listed.'),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 10, 'The onward lesson names a second source of terminal negatives beside abandonment. What is it?', '["A price deck that falls in its last entries, which turns the late revenue rows negative before the cascade is applied to them.", "Mid-year discounting, which discounts the valuation year row and so pushes a negative into the tail of the discounted column.", "A tail kept past its economic limit with the limit test off, where each late year carries a loss to the end of the vector.", "A working interest below 100 percent, which scales the late rows harder than the early ones and turns the tail negative at 25 percent."]'::jsonb, 2, 'At 20 percent decline the limit year is 2031 and three years are trimmed; with the limit off those years would stay, and each would carry a loss.', 'The onward lesson names a second source of terminal negatives beside abandonment. What is it?', '["A price deck that falls in its last entries, which turns the late revenue rows negative before the cascade is applied to them.", "Mid-year discounting, which moves the valuation year row by half a year and so pushes a negative into the tail of the discounted column.", "A tail kept past its economic limit with the limit test off, where each late year carries a loss to the end of the vector.", "A working interest below 100 percent, which scales the late rows harder than the early ones and turns the tail negative at 25 percent."]'::jsonb, 2, 'At 20 percent decline the limit year is 2031 and three years are trimmed; with the limit off those years would stay, and each would carry a loss.'),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 12, 'What does the capstone method refuse to produce?', '["One number: it produces a labelled set, and a reader asked for the NPV answers with the label attached.", "A mid-year figure, since the engine defaults to end-year and the method follows the engine''s default.", "An IRR on a real basis run, since 29.2361 percent is solved on the nominal flows and the method is worked on the real basis.", "A profile, since the method reads only the headline at the applied rate and leaves the seven sampled points to the sensitivity work."]'::jsonb, 0, 'AKATA''s 72534830.66, 70188970.32, 77464382.26 and 206819768.67 are all NPVs of the same rows, and only the label tells them apart.', 'What does the capstone method refuse to produce?', '["One number: it produces a labelled set, and a reader asked for the NPV answers with the label attached.", "A mid-year figure, since the engine defaults to end-year and the method follows the engine''s default.", "An IRR on a real basis run, since 29.2361 percent is solved on the nominal flows and the method is worked on the real basis.", "A profile, since the method reads only the headline at the applied rate and leaves the seven sampled points to the sensitivity work."]'::jsonb, 0, 'AKATA''s 72534830.66, 74959094.51, 77464382.26 and 206819768.67 are all NPVs of the same rows, and only the label tells them apart.'),
      ('intermediate', 'module', 'm06-the-professional-reading'::text, 15, 'The Professional tier hands on two readings that carry their own proof: the applied-rate profile point and the IRR of a vector whose last entry is negative. What does each tell a reader?', '["The point labelled 6.8 is a rounded estimate to be corrected against the headline, and [-100, 208, -108.12] returns 6.0000 percent, the root the search reaches first from 10 percent.", "The profile point reads the headline, and [-100, 208, -108.12] returns 2.0000 percent, the lower root, which the contract keeps as the conservative rate for a hurdle.", "Both are superseded by the breakeven residual of 897.16 and the mid-year NPV of 70188970.32, the readings the engine reports without saying how.", "The point labelled 6.8 reads the headline 72534830.66 because it is evaluated at the exact rate, and [-100, 208, -108.12] is null with multiple-roots and both roots listed."]'::jsonb, 3, 'The applied-rate point is labelled at the rate rounded to two decimals and evaluated at 6.796117, so it equals the headline; a vector with two crossings in the band is null with its roots listed. 70188970.32 and 897.16 are correct readings under their labels.', 'The Professional tier hands on two readings that carry their own proof: the applied-rate profile point and the IRR of a vector whose last entry is negative. What does each tell a reader?', '["The point labelled 6.8 is a rounded estimate to be corrected against the headline, and [-100, 208, -108.12] returns 6.0000 percent, the root the search reaches first from 10 percent.", "The profile point reads the headline, and [-100, 208, -108.12] returns 2.0000 percent, the lower root, which the contract keeps as the conservative rate for a hurdle.", "Both are superseded by the breakeven residual of 897.16 and the mid-year NPV of 74959094.51, the readings the engine reports without saying how.", "The point labelled 6.8 reads the headline 72534830.66 because it is evaluated at the exact rate, and [-100, 208, -108.12] is null with multiple-roots and both roots listed."]'::jsonb, 3, 'The applied-rate point is labelled at the rate rounded to two decimals and evaluated at 6.796117, so it equals the headline; a vector with two crossings in the band is null with its roots listed. 74959094.51 and 897.16 are correct readings under their labels.')
    ) as v(tier, scope, module_key, ord, old_prompt, old_options, old_answer, old_expl, new_prompt, new_options, new_answer, new_expl)
  loop
    select case
             when q.prompt = r.old_prompt and q.options = r.old_options and q.answer_index = r.old_answer and q.explanation is not distinct from r.old_expl then 'old'
             when q.prompt = r.new_prompt and q.options = r.new_options and q.answer_index = r.new_answer and q.explanation is not distinct from r.new_expl then 'new'
             else 'other' end
      into v_state
      from public.academy_quiz_questions q
     where q.app_slug = 'cashflow' and q.active and q.tier = r.tier and q.scope = r.scope
       and q.module_key is not distinct from r.module_key and q.ord = r.ord;
    get diagnostics v_count = row_count;
    if v_count <> 1 then
      raise exception 'ec1 midyear recut refused: cashflow/%/%/%/ord % matched % active rows, expected 1', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord, v_count;
    end if;
    if v_state = 'other' then
      raise exception 'ec1 midyear recut refused: cashflow/%/%/%/ord % carries neither its served text nor the recut text', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord;
    end if;
    if v_state = 'old' then
      update public.academy_quiz_questions q
         set prompt = r.new_prompt, options = r.new_options, answer_index = r.new_answer, explanation = r.new_expl
       where q.app_slug = 'cashflow' and q.active and q.tier = r.tier and q.scope = r.scope
         and q.module_key is not distinct from r.module_key and q.ord = r.ord;
      get diagnostics v_count = row_count;
      if v_count <> 1 then
        raise exception 'ec1 midyear recut refused: cashflow/%/%/%/ord % update touched % rows', r.tier, r.scope, coalesce(r.module_key, 'final'), r.ord, v_count;
      end if;
      v_updated := v_updated + 1;
    else
      v_done := v_done + 1;
    end if;
  end loop;
  for r in select t as tier from unnest(array['beginner', 'intermediate', 'advanced']) t loop
    select count(*) into v_count from public.academy_quiz_questions where app_slug = 'cashflow' and active and tier = r.tier;
    if v_count <> 132 then
      raise exception 'ec1 midyear recut refused: cashflow/% holds % active questions, expected 132', r.tier, v_count;
    end if;
  end loop;
  raise notice 'ec1 midyear recut: cashflow questions, % updated, % already recut, of 21', v_updated, v_done;
end $$;

-- 2. cashflow Professional capstone: the mid-year sentence and jv_npv_mid_year_usd.
do $$
declare
  v_state text;
  v_count integer;
begin
  select case
           when c.prompt = 'Six values for the same IKPOTO joint venture run as the Associate capstone (identical rows and terms), now valued at a 9 percent NOMINAL discount rate on the REAL basis with 2.5 percent inflation, valuation year equal to the 2031 base year, nothing sunk. Report: (1) the NPV under END-YEAR discounting; (2) the NPV under MID-YEAR discounting; (3) the INTERNAL RATE OF RETURN in percent; (4) the DISCOUNTED PAYBACK in years; (5) the DPI (NPV over the present value of capex); and (6) the BREAKEVEN flat oil price in USD/bbl at which the end-year NPV is nought. Traps. The applied rate is the Fisher REAL rate, (1.09 / 1.025) - 1, which is below 9 percent, and the flows it discounts are the DEFLATED flows; discounting the nominal flows at 9 percent gives the same NPV, which is the point, but discounting the deflated flows at 9 percent does not. Mid-year adds one half to every exponent including the first. IRR is solved on the NOMINAL flows and does not depend on the basis. DPI here is NPV over PV(capex), which is the profitability index MINUS ONE; report the engine''s definition. The breakeven is the FLAT price with the 1.5 percent escalator still applied from it, found by bisection to the cent.'
            and (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements(c.fields) with ordinality as e(f, n)) = (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements('[{"key": "jv_npv_real_usd", "tol": 1, "unit": "USD", "label": "NPV, real basis, end year", "expected": 20656337.21686185}, {"key": "jv_npv_mid_year_usd", "tol": 1, "unit": "USD", "label": "NPV, real basis, mid year", "expected": 20030970.834339857}, {"key": "jv_irr_pct", "tol": 0.0001, "unit": "percent", "label": "Internal rate of return", "expected": 23.719272956750835}, {"key": "jv_discounted_payback_years", "tol": 0.0001, "unit": "years", "label": "Discounted payback", "expected": 3.9696530221864026}, {"key": "jv_dpi", "tol": 1e-06, "unit": "ratio", "label": "Discounted profitability index", "expected": 0.17502648916650668}, {"key": "jv_breakeven_oil_price_usd_bbl", "tol": 0.005, "unit": "USD/bbl", "label": "Breakeven oil price", "expected": 66.10100889205933}]'::jsonb) with ordinality as e(f, n)) then 'old'
           when c.prompt = 'Six values for the same IKPOTO joint venture run as the Associate capstone (identical rows and terms), now valued at a 9 percent NOMINAL discount rate on the REAL basis with 2.5 percent inflation, valuation year equal to the 2031 base year, nothing sunk. Report: (1) the NPV under END-YEAR discounting; (2) the NPV under MID-YEAR discounting; (3) the INTERNAL RATE OF RETURN in percent; (4) the DISCOUNTED PAYBACK in years; (5) the DPI (NPV over the present value of capex); and (6) the BREAKEVEN flat oil price in USD/bbl at which the end-year NPV is nought. Traps. The applied rate is the Fisher REAL rate, (1.09 / 1.025) - 1, which is below 9 percent, and the flows it discounts are the DEFLATED flows; discounting the nominal flows at 9 percent gives the same NPV, which is the point, but discounting the deflated flows at 9 percent does not. Mid-year takes one half from every exponent, the first included, because the valuation date is 31 December and mid-year cash arrives half a year before it. IRR is solved on the NOMINAL flows and does not depend on the basis. DPI here is NPV over PV(capex), which is the profitability index MINUS ONE; report the engine''s definition. The breakeven is the FLAT price with the 1.5 percent escalator still applied from it, found by bisection to the cent.'
            and (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements(c.fields) with ordinality as e(f, n)) = (select string_agg((e.f->>'key') || '|' || coalesce(e.f->>'label', '') || '|' || coalesce(e.f->>'unit', '') || '|' || ((e.f->>'expected')::float8)::text || '|' || ((e.f->>'tol')::float8)::text, ',' order by e.n) from jsonb_array_elements('[{"key": "jv_npv_real_usd", "tol": 1, "unit": "USD", "label": "NPV, real basis, end year", "expected": 20656337.21686185}, {"key": "jv_npv_mid_year_usd", "tol": 1, "unit": "USD", "label": "NPV, real basis, mid year", "expected": 21301227.52139557}, {"key": "jv_irr_pct", "tol": 0.0001, "unit": "percent", "label": "Internal rate of return", "expected": 23.719272956750835}, {"key": "jv_discounted_payback_years", "tol": 0.0001, "unit": "years", "label": "Discounted payback", "expected": 3.9696530221864026}, {"key": "jv_dpi", "tol": 1e-06, "unit": "ratio", "label": "Discounted profitability index", "expected": 0.17502648916650668}, {"key": "jv_breakeven_oil_price_usd_bbl", "tol": 0.005, "unit": "USD/bbl", "label": "Breakeven oil price", "expected": 66.10100889205933}]'::jsonb) with ordinality as e(f, n)) then 'new'
           else 'other' end
    into v_state
    from public.academy_capstones c where c.app_slug = 'cashflow' and c.tier = 'intermediate' and c.active;
  get diagnostics v_count = row_count;
  if v_count <> 1 then
    raise exception 'ec1 midyear recut refused: cashflow/intermediate has % active capstones, expected 1', v_count;
  end if;
  if v_state = 'other' then
    raise exception 'ec1 midyear recut refused: the cashflow/intermediate capstone carries neither its served prompt and fields nor the recut ones';
  end if;
  if v_state = 'old' then
    update public.academy_capstones
       set prompt = 'Six values for the same IKPOTO joint venture run as the Associate capstone (identical rows and terms), now valued at a 9 percent NOMINAL discount rate on the REAL basis with 2.5 percent inflation, valuation year equal to the 2031 base year, nothing sunk. Report: (1) the NPV under END-YEAR discounting; (2) the NPV under MID-YEAR discounting; (3) the INTERNAL RATE OF RETURN in percent; (4) the DISCOUNTED PAYBACK in years; (5) the DPI (NPV over the present value of capex); and (6) the BREAKEVEN flat oil price in USD/bbl at which the end-year NPV is nought. Traps. The applied rate is the Fisher REAL rate, (1.09 / 1.025) - 1, which is below 9 percent, and the flows it discounts are the DEFLATED flows; discounting the nominal flows at 9 percent gives the same NPV, which is the point, but discounting the deflated flows at 9 percent does not. Mid-year takes one half from every exponent, the first included, because the valuation date is 31 December and mid-year cash arrives half a year before it. IRR is solved on the NOMINAL flows and does not depend on the basis. DPI here is NPV over PV(capex), which is the profitability index MINUS ONE; report the engine''s definition. The breakeven is the FLAT price with the 1.5 percent escalator still applied from it, found by bisection to the cent.',
           fields = '[{"key": "jv_npv_real_usd", "tol": 1, "unit": "USD", "label": "NPV, real basis, end year", "expected": 20656337.21686185}, {"key": "jv_npv_mid_year_usd", "tol": 1, "unit": "USD", "label": "NPV, real basis, mid year", "expected": 21301227.52139557}, {"key": "jv_irr_pct", "tol": 0.0001, "unit": "percent", "label": "Internal rate of return", "expected": 23.719272956750835}, {"key": "jv_discounted_payback_years", "tol": 0.0001, "unit": "years", "label": "Discounted payback", "expected": 3.9696530221864026}, {"key": "jv_dpi", "tol": 1e-06, "unit": "ratio", "label": "Discounted profitability index", "expected": 0.17502648916650668}, {"key": "jv_breakeven_oil_price_usd_bbl", "tol": 0.005, "unit": "USD/bbl", "label": "Breakeven oil price", "expected": 66.10100889205933}]'::jsonb
     where app_slug = 'cashflow' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then
      raise exception 'ec1 midyear recut refused: the cashflow/intermediate capstone update touched % rows', v_count;
    end if;
  end if;
  raise notice 'ec1 midyear recut: cashflow/intermediate capstone %', case when v_state = 'old' then 'recut' else 'already recut' end;
end $$;

-- 3. Closing assertions.
do $$
declare
  v_count integer;
begin
  select count(*) into v_count from public.academy_quiz_questions where app_slug = 'cashflow' and active;
  if v_count <> 396 then
    raise exception 'ec1 midyear recut refused: cashflow holds % active questions, expected 396', v_count;
  end if;
  select count(*) into v_count from public.academy_capstones where app_slug = 'cashflow' and active;
  if v_count <> 3 then
    raise exception 'ec1 midyear recut refused: cashflow has % active capstones, expected 3', v_count;
  end if;
  select count(*) into v_count from public.academy_capstones k, lateral jsonb_array_elements(k.fields) f where k.app_slug = 'cashflow' and k.active;
  if v_count <> 18 then
    raise exception 'ec1 midyear recut refused: cashflow capstones carry % graded fields, expected 18', v_count;
  end if;
  if current_setting('ec1mid.snapshot', true) is distinct from md5(coalesce((select string_agg(md5(a::text), ',' order by a.id) from public.academy_capstone_attempts a where a.app_slug = 'cashflow'), '') || '#' || coalesce((select string_agg(md5(q::text), ',' order by q.id) from public.academy_quiz_attempts q where q.app_slug = 'cashflow'), '') || '#' || coalesce((select string_agg(md5(c::text), ',' order by c.id) from public.academy_certifications c where c.app_slug = 'cashflow'), '')) then
    raise exception 'ec1 midyear recut refused: a stored cashflow quiz attempt, capstone attempt or certification changed';
  end if;
  raise notice 'ec1 midyear recut: done; attempts and certifications untouched';
end $$;
